<?php
require dirname(__DIR__) . '/app/bootstrap.php';
require_permission('maintenance.manage');
$checks = [];
$checks[] = ['HTTPS request', ((!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https')) ? 'Detected' : 'Not detected', ((!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https')) ? 'ok' : 'warn'];
$checks[] = ['Session strict mode', ini_get('session.use_strict_mode') === '1' ? 'Enabled' : 'Check configuration', ini_get('session.use_strict_mode') === '1' ? 'ok' : 'warn'];
$checks[] = ['HTTP-only session cookie', ini_get('session.cookie_httponly') ? 'Enabled' : 'Check configuration', ini_get('session.cookie_httponly') ? 'ok' : 'warn'];
$checks[] = ['PHP version', PHP_VERSION, version_compare(PHP_VERSION, '8.1.0', '>=') ? 'ok' : 'warn'];
$checks[] = ['Password hashing', function_exists('password_verify') && function_exists('password_hash') ? 'Available' : 'Missing', function_exists('password_verify') && function_exists('password_hash') ? 'ok' : 'bad'];
$checks[] = ['CSRF protection', function_exists('verify_csrf') && function_exists('csrf_token') ? 'Available' : 'Missing', function_exists('verify_csrf') && function_exists('csrf_token') ? 'ok' : 'bad'];
$failedAttempts = null; $recentActivity = [];
try { $failedAttempts = (int)$pdo->query("SELECT COUNT(*) FROM login_attempts WHERE attempted_at >= (NOW() - INTERVAL 24 HOUR)")->fetchColumn(); } catch (Throwable $e) {}
try { $q=$pdo->query("SELECT action, admin_name, summary, created_at FROM admin_activity WHERE action LIKE 'auth.%' ORDER BY id DESC LIMIT 12"); $recentActivity=$q->fetchAll(); } catch (Throwable $e) {}
function security_status(string $status): string { return $status === 'ok' ? 'status-ok' : ($status === 'bad' ? 'status-bad' : 'status-warn'); }
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Security & Recovery — NOWRD</title><link rel="stylesheet" href="<?=e(base_url('public/assets/style.css'))?>"><style>.sec-wrap{max-width:1050px;margin:0 auto;padding:34px 24px}.sec-head{margin-bottom:24px}.sec-head h1{font-size:clamp(30px,4vw,44px);letter-spacing:-.05em;margin:8px 0}.sec-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.sec-card{background:var(--surface,#fff);border:1px solid var(--line,#e5e7eb);border-radius:18px;padding:22px;min-width:0}.sec-card h2{font-size:18px;margin:0 0 10px}.sec-muted{color:var(--muted,#6b7280);font-size:13px;line-height:1.7}.sec-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid var(--line,#e5e7eb);font-size:13px}.sec-row:last-child{border-bottom:0}.sec-status{font-size:11px;font-weight:700;border-radius:999px;padding:5px 8px;white-space:nowrap}.status-ok{background:#dcfce7;color:#166534}.status-warn{background:#fef3c7;color:#92400e}.status-bad{background:#fee2e2;color:#991b1b}.sec-callout{padding:13px 15px;border-radius:12px;background:var(--soft,#f3f4f6);font-size:12px;line-height:1.7;margin-top:14px}.sec-table{width:100%;border-collapse:collapse;font-size:12px}.sec-table th,.sec-table td{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line,#e5e7eb);vertical-align:top}.sec-table th{color:var(--muted,#6b7280)}.sec-wide{grid-column:1/-1}@media(max-width:700px){.sec-grid{grid-template-columns:1fr}.sec-wide{grid-column:auto}.sec-wrap{padding:24px 14px}.sec-card{padding:17px}.sec-table{display:block;overflow-x:auto;white-space:nowrap}}</style></head><body class="dashboard"><aside class="sidebar"><a class="brand" href="<?=e(base_url('admin/index.php'))?>"><span class="brand-mark"><?=e(setting('brand_mark','n.'))?></span> <?=e(setting('brand_name','NOWRD'))?></a><div class="side-label">WORKSPACE</div><a class="side-link" href="<?=e(base_url('admin/index.php'))?>">▦ &nbsp; Overview</a><a class="side-link" href="<?=e(base_url('admin/post.php'))?>">✎ &nbsp; New story</a><a class="side-link" href="<?=e(base_url('admin/media.php'))?>">▧ &nbsp; Media Library</a><a class="side-link" href="<?=e(base_url('admin/settings.php'))?>">⚙ &nbsp; Settings</a><a class="side-link" href="<?=e(base_url('admin/maintenance.php'))?>">⌁ &nbsp; Maintenance</a><a class="side-link active" href="<?=e(base_url('admin/security.php'))?>">♢ &nbsp; Security & Recovery</a><a class="side-link" href="<?=e(base_url('index.php'))?>">↗ &nbsp; View website</a></aside><main class="admin-main"><div class="sec-wrap"><header class="sec-head"><div class="eyebrow">WORKSPACE / PROTECTION</div><h1>Security & Recovery<span class="lime">.</span></h1><p class="sec-muted">Ringkasan pemeriksaan keamanan dan panduan pemulihan. Status ini membantu pemeriksaan awal, bukan pengganti audit penetrasi.</p></header><div class="sec-grid"><section class="sec-card"><h2>Security checks</h2><p class="sec-muted">Deteksi konfigurasi pada request saat ini.</p><?php foreach($checks as $c):?><div class="sec-row"><span><?=e($c[0])?></span><span class="sec-status <?=e(security_status($c[2]))?>"><?=e($c[1])?></span></div><?php endforeach;?><div class="sec-callout">Jika HTTPS tidak terdeteksi padahal situs menggunakan HTTPS, periksa konfigurasi reverse proxy di hosting. Jangan mengaktifkan HSTS sebelum HTTPS dipastikan bekerja di seluruh domain.</div></section><section class="sec-card"><h2>Login monitoring</h2><p class="sec-muted">Percobaan login yang direkam dalam database.</p><div class="sec-row"><span>Percobaan login 24 jam terakhir</span><strong><?= $failedAttempts === null ? 'Tidak tersedia' : number_format($failedAttempts) ?></strong></div><p class="sec-muted">Rate limiter bawaan menahan login setelah 5 percobaan dalam jendela 15 menit berdasarkan IP hash atau email. Pastikan tabel <code>login_attempts</code> dapat ditulis.</p><div class="sec-callout">Gunakan password unik dan panjang, akun terpisah sesuai peran, serta HTTPS. Jangan membagikan akun administrator bersama.</div></section><section class="sec-card sec-wide"><h2>Recent authentication activity</h2><p class="sec-muted">Riwayat auth yang tersedia; detail sensitif tidak ditampilkan.</p><div style="overflow-x:auto"><table class="sec-table"><thead><tr><th>Waktu</th><th>Akun</th><th>Aktivitas</th><th>Catatan</th></tr></thead><tbody><?php if(!$recentActivity):?><tr><td colspan="4">Belum ada aktivitas autentikasi yang tersedia.</td></tr><?php else: foreach($recentActivity as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e($a['admin_name'])?></td><td><?=e($a['action'])?></td><td><?=e($a['summary'])?></td></tr><?php endforeach; endif;?></tbody></table></div></section><section class="sec-card"><h2>Backup checklist</h2><p class="sec-muted">Sebelum upgrade, lakukan semua langkah berikut.</p><div class="sec-row"><span>Database dump disimpan privat</span><span>□</span></div><div class="sec-row"><span>Folder <code>uploads/</code> dicadangkan</span><span>□</span></div><div class="sec-row"><span><code>config.php</code> dicadangkan dengan aman</span><span>□</span></div><div class="sec-row"><span>Restore diuji di database terpisah</span><span>□</span></div></section><section class="sec-card"><h2>Recovery procedure</h2><p class="sec-muted">1. Aktifkan maintenance di tingkat hosting jika diperlukan.<br>2. Simpan salinan versi saat ini sebelum mengubah file.<br>3. Pulihkan database ke database kosong/terpisah terlebih dahulu.<br>4. Pulihkan media dan konfigurasi yang sesuai.<br>5. Uji login, artikel, upload, tema, dan URL publik sebelum membuka kembali situs.</p><div class="sec-callout">Halaman ini tidak menjalankan pemulihan otomatis. Memulihkan dump SQL dapat menimpa atau menghapus data jika dijalankan pada database yang salah.</div></section></div></div></main></body></html>
